export type ToolOptions<TParameters extends ToolInputParameters> = {
  name?: string;
  description: string;
  parameters?: TParameters;
  execute: ToolExecuteFunction<TParameters>;
  isLongRunning?: boolean;
};

export type ToolInputParameters =
  | z3.ZodObject<z3.ZodRawShape>
  | z4.ZodObject<z4.ZodRawShape>
  | Schema
  | undefined;

constructor(options: ToolOptions<TParameters>) {
  const name = options.name ?? (options.execute as {name?: string}).name;
  if (!name) {
    throw new Error(
      'Tool name cannot be empty. Either name the `execute` function or provide a `name`.'
    );
  }
  super({
    name,
    description: options.description,
    isLongRunning: options.isLongRunning,
  });
  this.execute = options.execute;
  this.parameters = options.parameters;
}

override async runAsync(req: RunAsyncToolRequest): Promise<unknown> {
  try {
    let validatedArgs: unknown = req.args;
    if (isZodObject(this.parameters)) {
      validatedArgs = this.parameters.parse(req.args);
    }
    return await this.execute(
      validatedArgs as ToolExecuteArgument<TParameters>,
      req.toolContext,
    );
  } catch (error) {
    const errorMessage =
      error instanceof Error ? error.message : String(error);
    throw new Error(`Error in tool '${this.name}': ${errorMessage}`);
  }
}

export interface AgentToolConfig {
  agent: BaseAgent;
  skipSummarization?: boolean;
}

override async runAsync({
  args,
  toolContext,
}: RunAsyncToolRequest): Promise<unknown> {
  if (this.skipSummarization) {
    toolContext.actions.skipSummarization = true;
  }

  const hasInputSchema = isLlmAgent(this.agent) && this.agent.inputSchema;
  const content: Content = {
    role: 'user',
    parts: [
      {
        text: hasInputSchema
          ? JSON.stringify(args)
          : (args['request'] as string),
      },
    ],
  };

  const runner = new Runner({
    appName: this.agent.name,
    agent: this.agent,
    artifactService: new ForwardingArtifactService(toolContext),
    sessionService: new InMemorySessionService(),
    memoryService: new InMemoryMemoryService(),
    credentialService: toolContext.invocationContext.credentialService,
  });

  const session = await runner.sessionService.createSession({
    appName: this.agent.name,
    userId: 'tmp_user',
    state: toolContext.state.toRecord(),
  });

  let lastEvent: Event | undefined;
  for await (const event of runner.runAsync({
    userId: session.userId,
    sessionId: session.id,
    newMessage: content,
  })) {
    if (event.actions.stateDelta) {
      toolContext.state.update(event.actions.stateDelta);
    }
    lastEvent = event;
  }

  if (!lastEvent?.content?.parts?.length) {
    return '';
  }

  const hasOutputSchema = isLlmAgent(this.agent) && this.agent.outputSchema;
  const mergedText = lastEvent.content.parts
    .map((part) => part.text)
    .filter((text) => text)
    .join('\n');

  return hasOutputSchema ? JSON.parse(mergedText) : mergedText;
}

