export class Gemini extends BaseLlm {
  private readonly apiKey?: string;
  protected readonly vertexai: boolean;
  private readonly project?: string;
  private readonly location?: string;
  private readonly headers?: Record<string, string>;

  constructor({model, apiKey, vertexai, project, location, headers}: GeminiParams) {
    if (!model) {
      model = 'gemini-2.5-flash';
    }
    super({model});

    const params = geminiInitParams({model, vertexai, project, location, apiKey});
    if (!params.vertexai && !params.apiKey) {
      throw new Error(
        'API key must be provided via constructor or GOOGLE_GENAI_API_KEY or GEMINI_API_KEY environment variable.'
      );
    }
    this.project = params.project;
    this.location = params.location;
    this.apiKey = params.apiKey;
    this.headers = headers;
    this.vertexai = !!params.vertexai;
  }

  static override readonly supportedModels: Array<string | RegExp> = [
    /gemini-.*/,
    /projects\/.+\/locations\/.+\/endpoints\/.+/,  // fine-tuned vertex endpoint
    /projects\/.+\/locations\/.+\/publishers\/google\/models\/gemini.+/,  // vertex gemini long name
  ];
}

override async *generateContentAsync(
  llmRequest: LlmRequest,
  stream = false,
): AsyncGenerator<LlmResponse, void> {
  this.preprocessRequest(llmRequest);
  this.maybeAppendUserContent(llmRequest);
  logger.info(
    `Sending out request, model: ${llmRequest.model}, backend: ${this.apiBackend}, stream: ${stream}`
  );

  if (llmRequest.config?.httpOptions) {
    llmRequest.config.httpOptions.headers = {
      ...llmRequest.config.httpOptions.headers,
      ...this.trackingHeaders,
    };
  }

  if (stream) {
    const streamResult = await this.apiClient.models.generateContentStream({
      model: llmRequest.model ?? this.model,
      contents: llmRequest.contents,
      config: llmRequest.config,
    });
    let thoughtText = '';
    let text = '';
    let usageMetadata;
    let lastResponse: GenerateContentResponse | undefined;

    for await (const response of streamResult) {
      lastResponse = response;
      const llmResponse = createLlmResponse(response);
      usageMetadata = llmResponse.usageMetadata;
      const firstPart = llmResponse.content?.parts?.[0];
      // Accumulates the text and thought text from the first part.
      if (firstPart?.text) {
        if ('thought' in firstPart && firstPart.thought) {
          thoughtText += firstPart.text;
        } else {
          text += firstPart.text;
        }
        llmResponse.partial = true;
      } else if ((thoughtText || text) && (!firstPart || !firstPart.inlineData)) {
        // Flushes the data if there's no more text.
        const parts: Part[] = [];
        if (thoughtText) {
          parts.push({text: thoughtText, thought: true});
        }
        if (text) {
          parts.push(createPartFromText(text));
        }
        yield {
          content: {role: 'model', parts},
          usageMetadata: llmResponse.usageMetadata,
        };
        thoughtText = '';
        text = '';
      }
      yield llmResponse;
    }
    // Final flush if text remains and finishReason is STOP
    if ((text || thoughtText) && lastResponse?.candidates?.[0]?.finishReason === FinishReason.STOP) {
      const parts: Part[] = [];
      if (thoughtText) {
        parts.push({text: thoughtText, thought: true} as Part);
      }
      if (text) {
        parts.push({text: text});
      }
      yield {content: {role: 'model', parts}, usageMetadata};
    }
  } else {
    const response = await this.apiClient.models.generateContent({
      model: llmRequest.model ?? this.model,
      contents: llmRequest.contents,
      config: llmRequest.config,
    });
    yield createLlmResponse(response);
  }
}

get apiClient(): GoogleGenAI {
  if (this._apiClient) {
    return this._apiClient;
  }
  if (this.vertexai) {
    this._apiClient = new GoogleGenAI({
      vertexai: this.vertexai,
      project: this.project,
      location: this.location,
      httpOptions: this.getHttpOptions(),
    });
  } else {
    this._apiClient = new GoogleGenAI({
      apiKey: this.apiKey,
      httpOptions: this.getHttpOptions(),
    });
  }
  return this._apiClient;
}

get apiBackend(): GoogleLLMVariant {
  if (!this._apiBackend) {
    this._apiBackend = this.apiClient.vertexai
      ? GoogleLLMVariant.VERTEX_AI
      : GoogleLLMVariant.GEMINI_API;
  }
  return this._apiBackend;
}

export class LLMRegistry {
  private static llmRegistryDict: Map<string | RegExp, BaseLlmType> = new Map();
  private static resolveCache = new LRUCache<string, BaseLlmType>(32);

  static newLlm(model: string): BaseLlm {
    return new (LLMRegistry.resolve(model))({model});
  }

  private static _register(
    modelNameRegex: string | RegExp,
    llmCls: BaseLlmType,
  ) {
    if (LLMRegistry.llmRegistryDict.has(modelNameRegex)) {
      logger.info(
        `Updating LLM class for ${modelNameRegex} from ${LLMRegistry.llmRegistryDict.get(modelNameRegex)} to ${llmCls}`
      );
    }
    LLMRegistry.llmRegistryDict.set(modelNameRegex, llmCls);
  }

  static register<T extends BaseLlm>(
    llmCls: (new (params: {model: string}) => T) & {
      readonly supportedModels: Array<string | RegExp>;
    },
  ) {
    for (const regex of llmCls.supportedModels) {
      LLMRegistry._register(regex, llmCls);
    }
  }

  static resolve(model: string): BaseLlmType {
    const cachedLlm = LLMRegistry.resolveCache.get(model);
    if (cachedLlm) {
      return cachedLlm;
    }

    for (const [regex, llmClass] of LLMRegistry.llmRegistryDict.entries()) {
      // Replicates Python's `re.fullmatch` by anchoring the regex
      const pattern = new RegExp(
        `^${regex instanceof RegExp ? regex.source : regex}$`,
        regex instanceof RegExp ? regex.flags : undefined,
      );
      if (pattern.test(model)) {
        LLMRegistry.resolveCache.set(model, llmClass);
        return llmClass;
      }
    }

    throw new Error(`Model ${model} not found.`);
  }
}

