export class ApigeeLlm extends Gemini {
  private readonly proxyUrl: string;

  static override readonly supportedModels: Array<string | RegExp> = [
    /apigee\/.*/,
  ];

  constructor({model, proxyUrl, apiKey, vertexai, location, project, headers}: ApigeeLlmParams) {
    if (!validateModel(model)) {
      throw new Error(
        `Model ${model} is not a valid Apigee model, expected apigee/[<provider>/][<version>/]<model_id>`
      );
    }

    super({
      ...apigeeToGeminiInitParams({model, vertexai, project, location, apiKey}),
      headers,
    });

    this.proxyUrl = proxyUrl ?? '';
    if (!isBrowser() && !this.proxyUrl) {
      this.proxyUrl = process.env[APIGEE_PROXY_URL_ENV_VARIABLE_NAME] ?? '';
    }
    if (!this.proxyUrl) {
      throw new Error(
        `Proxy URL must be provided via the constructor or ${APIGEE_PROXY_URL_ENV_VARIABLE_NAME} environment variable.`
      );
    }
  }

  protected override getHttpOptions(): HttpOptions {
    const opts = super.getHttpOptions();
    opts.baseUrl = this.proxyUrl;
    return opts;
  }

  override async *generateContentAsync(
    llmRequest: LlmRequest,
    stream = false,
  ): AsyncGenerator<LlmResponse, void> {
    const modelToUse = llmRequest.model ?? this.model;
    llmRequest.model = getModelId(modelToUse);
    yield* super.generateContentAsync(llmRequest, stream);
  }
}

function apigeeToGeminiInitParams({model, vertexai, project, location, apiKey}: GeminiParams) {
  const params = geminiInitParams({model, vertexai, project, location, apiKey});
  params.vertexai = params.vertexai || params.model?.startsWith('apigee/vertex_ai/');
  if (params.vertexai) {
    return params;
  }
  if (!params.apiKey) {
    logger.warn(
      `No API key provided when using a Gemini model, using a fake key "-".`
    );
    params.apiKey = '-';
  }
  return params;
}

function getModelId(model: string): string {
  if (!validateModel(model)) {
    throw new Error(
      `Model ${model} is not a valid Apigee model, expected apigee/[<provider>/][<version>/]<model_id>`
    );
  }
  const components = model.split('/');
  return components[components.length - 1];
}

export interface LlmRequest {
  model?: string;
  contents: Content[];
  /**
   * Additional config for the generate content request.
   * Tools in generateContentConfig should not be set directly; use appendTools.
   */
  config?: GenerateContentConfig;
  liveConnectConfig: LiveConnectConfig;
  /**
   * The tools dictionary. Excluded from JSON serialization.
   */
  toolsDict: {[key: string]: BaseTool};
}

export function appendInstructions(
  llmRequest: LlmRequest,
  instructions: string[],
): void {
  if (!llmRequest.config) {
    llmRequest.config = {};
  }
  const newInstructions = instructions.join('\n\n');
  if (llmRequest.config.systemInstruction) {
    llmRequest.config.systemInstruction += '\n\n' + newInstructions;
  } else {
    llmRequest.config.systemInstruction = newInstructions;
  }
}

export function appendTools(llmRequest: LlmRequest, tools: BaseTool[]): void {
  if (!tools?.length) {
    return;
  }

  const functionDeclarations: FunctionDeclaration[] = [];
  for (const tool of tools) {
    const declaration = tool._getDeclaration();
    if (declaration) {
      functionDeclarations.push(declaration);
      llmRequest.toolsDict[tool.name] = tool;
    }
  }

  if (functionDeclarations.length) {
    if (!llmRequest.config) {
      llmRequest.config = {};
    }
    if (!llmRequest.config.tools) {
      llmRequest.config.tools = [];
    }
    llmRequest.config.tools.push({functionDeclarations});
  }
}

export function setOutputSchema(
  llmRequest: LlmRequest,
  schema: SchemaUnion,
): void {
  if (!llmRequest.config) {
    llmRequest.config = {};
  }
  llmRequest.config.responseSchema = schema;
  llmRequest.config.responseMimeType = 'application/json';
}

export interface LlmResponse {
  content?: Content;
  groundingMetadata?: GroundingMetadata;
  partial?: boolean;
  turnComplete?: boolean;
  errorCode?: string;
  errorMessage?: string;
  interrupted?: boolean;
  customMetadata?: {[key: string]: unknown};
  usageMetadata?: GenerateContentResponseUsageMetadata;
  finishReason?: FinishReason;
  liveSessionResumptionUpdate?: LiveServerSessionResumptionUpdate;
  inputTranscription?: Transcription;
  outputTranscription?: Transcription;
}

export function createLlmResponse(
  response: GenerateContentResponse,
): LlmResponse {
  const usageMetadata = response.usageMetadata;

  if (response.candidates && response.candidates.length > 0) {
    const candidate = response.candidates[0];
    if (candidate.content?.parts && candidate.content.parts.length > 0) {
      return {
        content: candidate.content,
        groundingMetadata: candidate.groundingMetadata,
        usageMetadata: usageMetadata,
        finishReason: candidate.finishReason,
      };
    }

    return {
      errorCode: candidate.finishReason,
      errorMessage: candidate.finishMessage,
      usageMetadata: usageMetadata,
      finishReason: candidate.finishReason,
    };
  }

  if (response.promptFeedback) {
    return {
      errorCode: response.promptFeedback.blockReason,
      errorMessage: response.promptFeedback.blockReasonMessage,
      usageMetadata: usageMetadata,
    };
  }

  return {
    errorCode: 'UNKNOWN_ERROR',
    errorMessage: 'Unknown error.',
    usageMetadata: usageMetadata,
  };
}

export type BaseLlmType = (new (params: {model: string}) => BaseLlm) & {
  readonly supportedModels: Array<string | RegExp>;
};

static register<T extends BaseLlm>(
  llmCls: (new (params: {model: string}) => T) & {
    readonly supportedModels: Array<string | RegExp>;
  },
) {
  for (const regex of llmCls.supportedModels) {
    LLMRegistry._register(regex, llmCls);
  }
}

export abstract class BaseLlm {
  readonly model: string;

  constructor({model}: {model: string}) {
    this.model = model;
  }

  static readonly supportedModels: Array<string | RegExp> = [];

  abstract generateContentAsync(
    llmRequest: LlmRequest,
    stream?: boolean,
  ): AsyncGenerator<LlmResponse, void>;

  abstract connect(llmRequest: LlmRequest): Promise<BaseLlmConnection>;
}

export enum GoogleLLMVariant {
  VERTEX_AI = 'VERTEX_AI',
  GEMINI_API = 'GEMINI_API',
}

export function getGoogleLlmVariant() {
  return getBooleanEnvVar('GOOGLE_GENAI_USE_VERTEXAI')
    ? GoogleLLMVariant.VERTEX_AI
    : GoogleLLMVariant.GEMINI_API;
}

get apiBackend(): GoogleLLMVariant {
  if (!this._apiBackend) {
    this._apiBackend = this.apiClient.vertexai
      ? GoogleLLMVariant.VERTEX_AI
      : GoogleLLMVariant.GEMINI_API;
  }
  return this._apiBackend;
}

private preprocessRequest(llmRequest: LlmRequest): void {
  if (this.apiBackend === GoogleLLMVariant.GEMINI_API) {
    if (llmRequest.config) {
      // Using API key from Google AI Studio to call model doesn't support labels.
      (llmRequest.config as {labels?: unknown}).labels = undefined;
    }
    if (llmRequest.contents) {
      for (const content of llmRequest.contents) {
        if (!content.parts) continue;
        for (const part of content.parts) {
          removeDisplayNameIfPresent(part.inlineData);
          removeDisplayNameIfPresent(part.fileData);
        }
      }
    }
  }
}

function removeDisplayNameIfPresent(dataObj: Blob | FileData | undefined): void {
  // display_name is not supported for Gemini API (non-vertex)
  if (dataObj && (dataObj as FileData).displayName) {
    (dataObj as FileData).displayName = undefined;
  }
}

export interface Session {
  id: string;
  appName: string;
  userId: string;
  state: Record<string, unknown>;
  events: Event[];
  lastUpdateTime: number;
}

export function createSession(
  params: Partial<Session> & {id: string; appName: string},
): Session {
  return {
    id: params.id,
    appName: params.appName,
    userId: params.userId || '',
    state: params.state || {},
    events: params.events || [],
    lastUpdateTime: params.lastUpdateTime || 0,
  };
}

export interface CreateSessionRequest {
  appName: string;
  userId: string;
  state?: Record<string, unknown>;
  sessionId?: string;
}

export abstract class BaseSessionService {
  abstract createSession(request: CreateSessionRequest): Promise<Session>;
}

createSession({
  appName,
  userId,
  state,
  sessionId,
}: CreateSessionRequest): Promise<Session> {
  const session = createSession({
    id: sessionId || randomUUID(),
    appName,
    userId,
    state,
    events: [],
    lastUpdateTime: Date.now(),
  });

  if (!this.sessions[appName]) {
    this.sessions[appName] = {};
  }
  if (!this.sessions[appName][userId]) {
    this.sessions[appName][userId] = {};
  }

  this.sessions[appName][userId][session.id] = session;

  return Promise.resolve(this.mergeState(appName, userId, cloneDeep(session)));
}

export class State {
  static readonly APP_PREFIX = 'app:';
  static readonly USER_PREFIX = 'user:';
  static readonly TEMP_PREFIX = 'temp:';

  constructor(
    private value: Record<string, unknown> = {},
    private delta: Record<string, unknown> = {},
  ) {}

  get<T>(key: string, defaultValue?: T): T | undefined {
    if (key in this.delta) {
      return this.delta[key] as T;
    }
    if (key in this.value) {
      return this.value[key] as T;
    }
    return defaultValue;
  }

  set(key: string, value: unknown) {
    this.value[key] = value;
    this.delta[key] = value;
  }

  has(key: string): boolean {
    return key in this.value || key in this.delta;
  }

  hasDelta(): boolean {
    return Object.keys(this.delta).length > 0;
  }

  update(delta: Record<string, unknown>) {
    this.delta = {...this.delta, ...delta};
    this.value = {...this.value, ...delta};
  }

  toRecord(): Record<string, unknown> {
    return {...this.value, ...this.delta};
  }
}

private updateSessionState({session, event}: AppendEventRequest): void {
  if (!event.actions || !event.actions.stateDelta) {
    return;
  }
  for (const [key, value] of Object.entries(event.actions.stateDelta)) {
    if (key.startsWith(State.TEMP_PREFIX)) {
      continue;  // Skip temp: prefixed keys
    }
    session.state[key] = value;
  }
}

if (event.actions && event.actions.stateDelta) {
  for (const key of Object.keys(event.actions.stateDelta)) {
    if (key.startsWith(State.APP_PREFIX)) {
      this.appState[appName] = this.appState[appName] || {};
      this.appState[appName][key.replace(State.APP_PREFIX, '')] =
        event.actions.stateDelta[key];
    }

    if (key.startsWith(State.USER_PREFIX)) {
      this.userState[appName] = this.userState[appName] || {};
      this.userState[appName][userId] = this.userState[appName][userId] || {};
      this.userState[appName][userId][key.replace(State.USER_PREFIX, '')] =
        event.actions.stateDelta[key];
    }
  }
}

export abstract class BaseSessionService {
  abstract createSession(request: CreateSessionRequest): Promise<Session>;
  abstract getSession(request: GetSessionRequest): Promise<Session | undefined>;

  async getOrCreateSession(request: CreateSessionRequest): Promise<Session> {
    if (!request.sessionId) {
      return this.createSession(request);
    }
    const session = await this.getSession({
      appName: request.appName,
      userId: request.userId,
      sessionId: request.sessionId,
    });
    if (session) {
      return session;
    }
    return this.createSession(request);
  }

  abstract listSessions(request: ListSessionsRequest): Promise<ListSessionsResponse>;
  abstract deleteSession(request: DeleteSessionRequest): Promise<void>;

  async appendEvent({session, event}: AppendEventRequest): Promise<Event> {
    if (event.partial) {
      return event;
    }

    this.updateSessionState({session, event});
    session.events.push(event);

    return event;
  }

  private updateSessionState({session, event}: AppendEventRequest): void {
    if (!event.actions || !event.actions.stateDelta) {
      return;
    }
    for (const [key, value] of Object.entries(event.actions.stateDelta)) {
      if (key.startsWith(State.TEMP_PREFIX)) {
        continue;
      }
      session.state[key] = value;
    }
  }
}

export class InMemorySessionService extends BaseSessionService {
  private sessions: Record<string, Record<string, Record<string, Session>>> = {};
  private userState: Record<string, Record<string, Record<string, unknown>>> = {};
  private appState: Record<string, Record<string, unknown>> = {};
}

export interface GetSessionConfig {
  numRecentEvents?: number;
  afterTimestamp?: number;
}

getSession({
  appName,
  userId,
  sessionId,
  config,
}: GetSessionRequest): Promise<Session | undefined> {
  if (
    !this.sessions[appName] ||
    !this.sessions[appName][userId] ||
    !this.sessions[appName][userId][sessionId]
  ) {
    return Promise.resolve(undefined);
  }

  const session: Session = this.sessions[appName][userId][sessionId];
  const copiedSession = cloneDeep(session);

  if (config) {
    if (config.numRecentEvents) {
      copiedSession.events = copiedSession.events.slice(
        -config.numRecentEvents,
      );
    }
    if (config.afterTimestamp) {
      let i = copiedSession.events.length - 1;
      while (i >= 0) {
        if (copiedSession.events[i].timestamp < config.afterTimestamp) {
          break;
        }
        i--;
      }
      if (i >= 0) {
        copiedSession.events = copiedSession.events.slice(i + 1);
      }
    }
  }

  return Promise.resolve(this.mergeState(appName, userId, copiedSession));
}

